<script>
function toggleGroup(el){let list=el.parentElement.querySelector('ol');if(list){list.classList.toggle('hidden');el.textContent=list.classList.contains('hidden')?'›':'⌄'}}
document.querySelectorAll('input[name=size]').forEach(x=>x.addEventListener('change',()=>{document.body.classList.remove('small','large');if(x.value!=='standard')document.body.classList.add(x.value)}));
