const labels=['Comma','Semicolon','Apostrophe','Colon','Hyphen','Decimal point','Full stop (period)','Exclamation point','Open quote, question mark','Close quote','Bracket (parentheses)','Slash (fraction)'];
const patterns=[[0,1,3],[0,1,2,3],[2],[1,2,4,5],[3,5],[1,4],[1,2,3,4],[1,2,4],[2,3,5],[1,2,3,5],[1,2,4,5],[2,4]];
function cell(pattern){let d=document.createElement('span');d.className='dots';for(let i=0;i<6;i++){let dot=document.createElement('i');dot.className='dot'+(pattern.includes(i)?' on':'');d.appendChild(dot)}return d}
for(let r=0;r<2;r++)for(let c=0;c<6;c++){let i=r*6+c,td=document.createElement('td');td.appendChild(cell(patterns[i]));let a=document.createElement('a');a.textContent=labels[i];td.appendChild(a);document.getElementById(r?'punct-row2':'punct-row').appendChild(td)}
